row(24, 1, 'MATERIAL', f'WHEN A MAN TAKES A WIFE AND HAS HER, AND SHE FINDS NO FAVOR IN HIS EYES BECAUSE HE FOUND IN HER AN UNSEEMLY THING, HE WRITES HER A BILL OF CUTTING OFF, GIVES IT IN HER HAND AND SENDS HER FROM HIS HOUSE. {HP(24, 1, (("כי", "יקח", "איש", "אשה", "ובעלה"), "when a man takes a wife and has her — 268:1-2\'s two acquisitions"), (("ערות", "דבר"), "an unseemly thing — 269:1\'s schools"), (("וכתב", "לה", "ספר", "כריתת", "ונתן", "בידה", "ושלחה"), "writes her a bill of cutting off, gives it in her hand and sends her — find 4\'s run of eight with 24:3"))} {AP(24, 1, (("עברת", "פתגם"), "A TRANSGRESSION OF A WORD — 23:15\'s phrase again"), (("גט", "פטורין"), "A BILL OF RELEASE (get piturin) — the answer sheet\'s own word for the bill, find 4"), (("ויפטרנה", "מביתיה"), "and release her from his house"))} Fresh.')
row(24, 2, 'MATERIAL', f'AND SHE GOES OUT OF HIS HOUSE AND GOES AND BECOMES ANOTHER MAN\'S. {HP(24, 2, (("ויצאה", "מביתו"), "she goes out of his house — 270:1"), (("והיתה", "לאיש", "אחר"), "and becomes another man\'s — 270:2-3"))} {AP(24, 2, (("ותהי", "לגבר", "אחרן"), "AND BE TO ANOTHER MAN"))} Fresh.')
row(24, 3, 'MATERIAL', f'AND THE LATTER MAN HATES HER AND WRITES HER A BILL OF CUTTING OFF, GIVES IT IN HER HAND AND SENDS HER FROM HIS HOUSE; OR THE LATTER MAN WHO TOOK HER TO WIFE DIES. {HP(24, 3, (("ושנאה", "האיש", "האחרון"), "the latter man hates her — 270:4"), (("או", "כי", "ימות", "האיש", "האחרון"), "or the latter man dies — 270:5-6"))} {AP(24, 3, (("ויסננה", "גברא", "בתראה"), "THE LATTER MAN HATES HER"), (("גט", "פטורין"), "the bill of release again"))} no head on 24:3 — 270:4-7 its rows. Fresh.')
row(24, 4, 'MATERIAL', f'HER FIRST HUSBAND WHO SENT HER AWAY MAY NOT TAKE HER AGAIN TO BE HIS WIFE AFTER SHE WAS DEFILED, FOR IT IS AN ABOMINATION BEFORE THE LORD; MAKE NOT THE LAND SIN WHICH THE LORD YOUR GOD GIVES YOU FOR AN INHERITANCE. {HP(24, 4, (("לא", "יוכל", "בעלה", "הראשון"), "her first husband may not — 270:8-9; the parser\'s ordinal [1]"), (("אחרי", "אשר", "הטמאה"), "after she was defiled — 270:10\'s sotah"), (("כי", "תועבה", "הוא", "לפני", "יהוה"), "for it is an abomination before the LORD — 270:12; find 5"))} {AP(24, 4, (("לית", "ליה", "רשו"), "HE HAS NO PERMISSION — \'may not\' as \'no permission\', 22:3\'s idiom"), (("מרחקא", "היא", "קדם", "יי"), "IT IS DISTANCED BEFORE THE LORD"), (("ולא", "תחיב", "ית", "ארעא"), "AND MAKE NOT THE LAND LIABLE — sin as liability (chov)"))} the gift formula\'s seat (find 9); no head on 24:4. Fresh.')
row(24, 5, 'MATERIAL', f'WHEN A MAN TAKES A NEW WIFE HE SHALL NOT GO OUT IN THE HOST NOR SHALL ANY MATTER PASS UPON HIM; FREE SHALL HE BE FOR HIS HOUSE ONE YEAR AND REJOICE HIS WIFE WHOM HE TOOK. {HP(24, 5, (("אשה", "חדשה"), "a new wife — 271:1\'s \'new to him\'"), (("נקי", "יהיה", "לביתו", "שנה", "אחת"), "free for his house one year — the parser\'s [1]; 271:3-5"))} {AP(24, 5, (("לא", "יפוק", "בחילא"), "HE SHALL NOT GO OUT IN THE HOST"), (("פני", "יהי", "לביתיה", "שתא", "חדא"), "free he shall be for his house one year"))} Fresh.')
row(24, 6, 'MATERIAL', f'HE SHALL NOT TAKE IN PLEDGE THE MILL AND THE UPPER STONE, FOR HE TAKES A LIFE IN PLEDGE. {HP(24, 6, (("לא", "יחבל", "רחים", "ורכב"), "take not in pledge the mill and the upper stone — 272:1"), (("כי", "נפש", "הוא", "חבל"), "for he takes a life in pledge — 272:2"))} {AP(24, 6, (("ארי", "בהון", "מתעבד", "מזון", "לכל", "נפש"), "FOR WITH THEM FOOD IS MADE FOR EVERY SOUL — the reason paraphrased: the livelihood, not the life"))} the verse with no kin (find 12). Fresh.')
row(24, 7, 'MATERIAL', f'IF A MAN BE FOUND STEALING A SOUL OF HIS BROTHERS OF THE CHILDREN OF ISRAEL, AND ENSLAVES HIM AND SELLS HIM, THAT THIEF SHALL DIE; PURGE THE EVIL FROM YOUR MIDST. {HP(24, 7, (("גנב", "נפש", "מאחיו"), "stealing a soul of his brothers — 273:3-4"), (("והתעמר", "בו", "ומכרו"), "and enslaves him and sells him — 273:5"), (("ובערת", "הרע", "מקרבך"), "purge the evil from your midst — the formula\'s last seat, find 6; 273:9"))} {AP(24, 7, (("ויתגר", "ביה"), "AND TRADES IN HIM — enslaving as trading"), (("ויתקטל", "גנבא", "ההוא"), "THAT THIEF SHALL BE KILLED"), (("ותפלי", "עבד", "דביש"), "AND PUT AWAY THE DOER OF EVIL — the formula\'s rendering, \'the evil\' a person"))} Fresh.')
row(24, 8, 'MATERIAL', f'TAKE HEED IN THE PLAGUE OF LEPROSY TO KEEP DILIGENTLY AND TO DO ALL THAT THE LEVITICAL PRIESTS TEACH YOU; AS I COMMANDED THEM YOU SHALL KEEP TO DO. {HP(24, 8, (("השמר", "בנגע", "הצרעת"), "take heed in the plague of leprosy — 274:1-3; the one imperative, find 14"), (("ככל", "אשר", "יורו", "אתכם", "הכהנים", "הלוים"), "as the levitical priests teach you — 274:4"))} {AP(24, 8, (("במכתש", "סגירו"), "IN THE PLAGUE OF SHUTTING-UP — leprosy named by its quarantine (segiru), 274:5\'s state"), (("די", "ילפון", "יתכון", "כהניא"), "which the priests teach you"))} the plural "you" (find 14). Fresh.')
row(24, 9, 'MATERIAL', f'REMEMBER WHAT THE LORD YOUR GOD DID TO MIRIAM ON THE WAY WHEN YOU CAME OUT OF EGYPT. {HP(24, 9, (("זכור", "את", "אשר", "עשה", "יהוה", "אלהיך", "למרים"), "remember what the LORD did to Miriam — 275:1; the infinitive absolute, find 2"), (("בדרך", "בצאתכם", "ממצרים"), "on the way when you came out of Egypt — 275:2-3"))} {AP(24, 9, (("הוי", "דכיר"), "BE REMEMBERING — the infinitive absolute as \'be mindful\', Exodus 20:8\'s form"))} Numbers 12 the tape\'s line behind. Fresh.')
row(24, 10, 'MATERIAL', f'WHEN YOU LEND YOUR FELLOW ANYTHING, COME NOT INTO HIS HOUSE TO TAKE HIS PLEDGE. {HP(24, 10, (("כי", "תשה", "ברעך", "משאת", "מאומה"), "when you lend your fellow anything — 276:1"), (("לא", "תבא", "אל", "ביתו"), "come not into his house — 276:2"))} {AP(24, 10, (("ארי", "תרשי", "בחברך", "רשו", "מדעם"), "WHEN YOU HAVE A CLAIM ON YOUR FELLOW OF ANYTHING"), (("למסב", "משכוניה"), "to take his pledge"))} the verse with no kin (find 12). Fresh.')
row(24, 11, 'MATERIAL', f'OUTSIDE YOU SHALL STAND, AND THE MAN YOU LEND TO SHALL BRING THE PLEDGE OUT TO YOU. {HP(24, 11, (("בחוץ", "תעמד"), "outside you shall stand — 276:2"), (("והאיש", "אשר", "אתה", "נשה", "בו"), "and the man you lend to — 276:3\'s court agent"))} {AP(24, 11, (("בברא", "תקום"), "OUTSIDE YOU SHALL STAND"), (("יפק", "לותך", "ית", "משכונא"), "shall bring out the pledge to you"))} no head on 24:11. Fresh.')
row(24, 12, 'MATERIAL', f'AND IF HE IS A POOR MAN, LIE NOT DOWN IN HIS PLEDGE. {HP(24, 12, (("ואם", "איש", "עני", "הוא"), "and if he is a poor man — 277:1"), (("לא", "תשכב", "בעבטו"), "lie not down in his pledge — 277:2"))} {AP(24, 12, (("גבר", "מסכן"), "A POOR MAN (miskena)"), (("לא", "תשכוב", "במשכוניה"), "lie not down with his pledge"))} Fresh.')
row(24, 13, 'MATERIAL', f'SURELY RETURN HIM THE PLEDGE AT SUNSET, THAT HE LIE IN HIS GARMENT AND BLESS YOU; AND IT SHALL BE RIGHTEOUSNESS TO YOU BEFORE THE LORD YOUR GOD. {HP(24, 13, (("השב", "תשיב", "לו", "את", "העבוט"), "surely return him the pledge — 277:3; the infinitive absolute"), (("כבא", "השמש"), "at sunset — the clock, 23:12\'s phrase"), (("ולך", "תהיה", "צדקה"), "and it shall be righteousness to you — 277:4-5"))} {AP(24, 13, (("כמעל", "שמשא"), "AT THE SUN\'S COMING IN"), (("ולך", "תהי", "זכותא"), "AND IT SHALL BE MERIT (zekhuta) TO YOU — righteousness as merit, find 15"))} no head on 24:13. Fresh.')
row(24, 14, 'MATERIAL', f'OPPRESS NOT A HIRELING POOR AND NEEDY OF YOUR BROTHERS OR OF YOUR SOJOURNER IN YOUR LAND IN YOUR GATES. {HP(24, 14, (("לא", "תעשק", "שכיר", "עני", "ואביון"), "oppress not a hireling poor and needy — 278:1-2; find 16"), (("או", "מגרך"), "or your sojourner — 278:4-5"))} {AP(24, 14, (("אגירא", "עניא", "ומסכנא"), "A HIRELING POOR AND NEEDY"), (("מגיורך",), "YOUR PROSELYTE — the sojourner as proselyte (giyora), 278:4\'s righteous proselyte"))} Fresh.')
row(24, 15, 'MATERIAL', f'ON HIS DAY GIVE HIS WAGE, AND LET NOT THE SUN SET ON IT, FOR HE IS POOR AND TO IT HE LIFTS HIS SOUL; THAT HE CRY NOT AGAINST YOU TO THE LORD AND IT BE SIN IN YOU. {HP(24, 15, (("ביומו", "תתן", "שכרו"), "on his day give his wage — 279:1"), (("ולא", "תבוא", "עליו", "השמש"), "and let not the sun set on it — 279:2"), (("ולא", "יקרא", "עליך", "אל", "יהוה", "והיה", "בך"), "that he cry not against you — 279:4; find 7\'s run of six with 15:9"))} {AP(24, 15, (("וליה", "הוא", "מסר", "ית", "נפשיה"), "AND TO IT HE GIVES OVER HIS LIFE — 279:3\'s ramp"), (("ויהי", "בך", "חובא"), "and there shall be guilt in you"))} Fresh.')
row(24, 16, 'MATERIAL', f'FATHERS SHALL NOT BE PUT TO DEATH FOR SONS, NOR SONS FOR FATHERS; EACH FOR HIS OWN SIN SHALL DIE. {HP(24, 16, (("לא", "יומתו", "אבות", "על", "בנים"), "fathers shall not die for sons — 280:1; find 1\'s 2 Kings 14:6"), (("איש", "בחטאו", "יומתו"), "each for his own sin — 280:3"))} {AP(24, 16, (("על", "פום", "בנין"), "BY THE MOUTH OF SONS — Onkelos writes 280:1\'s testimony into the verse: \'for\' rendered \'by the mouth of\'"), (("אנש", "בחוביה", "ימותון"), "each in his guilt shall die"))} the pointer OWED (2 Kings 14:6 ahead). Fresh.')
row(24, 17, 'MATERIAL', f'PERVERT NOT THE JUDGMENT OF THE SOJOURNER OR THE ORPHAN, AND TAKE NOT A WIDOW\'S GARMENT IN PLEDGE. {HP(24, 17, (("לא", "תטה", "משפט", "גר", "יתום"), "pervert not the judgment of sojourner and orphan — 281:1; 16:19\'s twin"), (("ולא", "תחבל", "בגד", "אלמנה"), "take not a widow\'s garment in pledge — 281:2-3"))} {AP(24, 17, (("לא", "תצלי", "דין", "גיורא", "ויתמא"), "BEND NOT THE JUDGMENT OF THE PROSELYTE AND THE ORPHAN"), (("לבוש", "ארמלא"), "a widow\'s garment"))} Fresh.')
row(24, 18, 'MATERIAL', f'REMEMBER THAT YOU WERE A SLAVE IN EGYPT AND THE LORD YOUR GOD REDEEMED YOU FROM THERE; THEREFORE I COMMAND YOU TO DO THIS THING. {HP(24, 18, (("וזכרת", "כי", "עבד", "היית", "במצרים"), "remember you were a slave in Egypt — find 3\'s refrain, 15:15\'s fourteen words"), (("אנכי", "מצוך"), "I command you — the store\'s \'?\' gloss on \'I\' (anokhi), the measure"))} {AP(24, 18, (("ופרקך", "יי", "אלהך", "מתמן"), "AND THE LORD YOUR GOD REDEEMED YOU FROM THERE"), (("אנא", "מפקדך"), "I command you"))} no head on 24:18. Fresh.')
row(24, 19, 'MATERIAL', f'WHEN YOU REAP YOUR HARVEST IN YOUR FIELD AND FORGET A SHEAF IN THE FIELD, RETURN NOT TO TAKE IT; FOR THE SOJOURNER, THE ORPHAN AND THE WIDOW LET IT BE, THAT THE LORD YOUR GOD MAY BLESS YOU IN ALL THE WORK OF YOUR HANDS. {HP(24, 19, (("כי", "תקצר", "קצירך", "בשדך"), "when you reap your harvest in your field — 282:1-4"), (("ושכחת", "עמר", "בשדה"), "and forget a sheaf in the field — 283:1-2"), (("לא", "תשוב", "לקחתו"), "return not to take it — 283:3-5"))} {AP(24, 19, (("ותנשי", "עמרא", "בחקלא"), "AND FORGET A SHEAF IN THE FIELD"), (("לגיורא", "ליתמא", "ולארמלא", "יהי"), "for the proselyte, the orphan and the widow let it be"))} Fresh.')
row(24, 20, 'MATERIAL', f'WHEN YOU BEAT YOUR OLIVE TREE, GO NOT OVER THE BOUGHS AFTER YOU; FOR THE SOJOURNER, THE ORPHAN AND THE WIDOW LET IT BE. {HP(24, 20, (("כי", "תחבט", "זיתך"), "when you beat your olive tree — 284:1"), (("לא", "תפאר", "אחריך"), "go not over the boughs after you — 284:3-5"))} {AP(24, 20, (("לא", "תפלי", "בתרך"), "SEARCH NOT AFTER YOU — the rare verb (pa\'er) rendered \'search out\' (pali), the same Aramaic root as 24:7\'s \'put away\' the evil: one Aramaic verb for two Hebrew ones"))} Fresh.')
